const LOCAL_GRAPH_NEIGHBORS: usize = DEFAULT_GRAPH_NEIGHBORS;
const ROUTING_SEARCH_PAGE_OVERFETCH: usize = 8;
/// Hard entry-count guard for one global term page.
const DEFAULT_LEXICAL_TERM_PAGE_ENTRIES: usize = 4096;
const TOMBSTONE_BUCKETS: u16 = 4096;
const CELL_WAL_MUTATION_METADATA_MAGIC: &[u8; 4] = b"BMM1";
const CELL_WAL_TOMBSTONE_METADATA_MAGIC: &[u8; 4] = b"BTM1";
const PACKED_INDEX_CONTROL_VERSION: u8 = 1;
const PACKED_INDEX_CONTROL_CHECKSUM_LEN: usize = 32;
const POSITIONED_PROJECTION_MAGIC: &[u8; 4] = b"BPR1";
const POSITIONED_TOMBSTONE_PROJECTION_SEPARATOR: char = '\0';
/// Stable authority epoch for the first production positioned-log incarnation.
/// A future epoch transition must publish an explicit collection-level marker;
/// it must never be derived from mutable manifest or snapshot generations.
const POSITIONED_SOURCE_EPOCH: u64 = INITIAL_POSITIONED_SOURCE_EPOCH;
/// Target decoded metadata working set of one global term page. The actual
/// builder accounts for variable paths/checksums, so high segment counts do not
/// turn a nominal page into an unbounded allocation.
const DEFAULT_LEXICAL_TERM_PAGE_BYTES: usize = 1024 * 1024;
/// Bound concurrent immutable-object reads for one batched point lookup.
/// Newest segments are still resolved first; only independent candidates in a
/// bounded window are fetched together to hide object-store RTT.
const POINT_READ_IO_BATCH: usize = 8;

fn elapsed_ns(started: Instant) -> u64 {
    started.elapsed().as_nanos().min(u128::from(u64::MAX)) as u64
}

fn parallel_segment_write_batch_size(segment_max_vectors: usize) -> usize {
    PARALLEL_SEGMENT_WRITE_RECORD_BUDGET
        .checked_div(segment_max_vectors.max(1))
        .unwrap_or(0)
        .clamp(1, MAX_PARALLEL_SEGMENT_WRITES)
}

fn join_rows(rows: &[usize]) -> String {
    rows.iter()
        .map(usize::to_string)
        .collect::<Vec<_>>()
        .join("|")
}

fn cell_wal_run_count(transactions: &[CommittedCellWalTransaction]) -> usize {
    transactions.len()
}

fn cell_wal_tombstone_run_count(transactions: &[CommittedCellWalTransaction]) -> usize {
    transactions
        .iter()
        .flat_map(|transaction| &transaction.runs)
        .filter(|run| run.kind == CellWalRunKind::Tombstones)
        .count()
}

/// Below this many cells a flat centroid scan is already cheap, so the HNSW
/// coarse quantizer stays off (building a graph would not pay for itself).
const COARSE_QUANTIZER_MIN_CELLS: usize = 128;
/// Cells the coarse quantizer returns per unit of the segment budget, so filter
/// pruning still leaves the full nprobe cells to read.
const COARSE_QUANTIZER_OVERFETCH: usize = 4;
/// Small, process-wide retention windows for immutable lexical objects.
///
/// These are deliberately fixed byte budgets rather than corpus-proportional
/// caches. They let staggered concurrent users reuse recently decoded Parquet
/// row groups/pages without making the complete postings index resident.
const DEFAULT_LEXICAL_RUN_CACHE_BYTES: u64 = 32 * 1024 * 1024;
const DEFAULT_LEXICAL_TERM_PAGE_CACHE_BYTES: u64 = 32 * 1024 * 1024;
const DEFAULT_TOMBSTONE_PAGE_CACHE_BYTES: u64 = 32 * 1024 * 1024;
/// Maximum complete mutation view admitted for bounded V12 leaf routing.
///
/// Larger overlays retain the ordinary query-paged MVCC architecture and make
/// V12 falls back before it reads a directory or leaf. The full reservation is
/// held while the view is live, so this optimization cannot silently turn a
/// 100M-row mutation map into unaccounted process memory.
const GLOBAL_LEAF_MVCC_OVERLAY_MAX_BYTES: u64 = 32 * 1024 * 1024;
const DEFAULT_BM25_STATS_PAGE_CACHE_BYTES: u64 = 16 * 1024 * 1024;
/// Bound concurrent immutable-segment publication by both object count and
/// records retained by the write wave. Tiny logical cells need enough parallel
/// PUTs to hide object-store latency, while production-sized segments must not
/// multiply the flush working set.
const MAX_PARALLEL_SEGMENT_WRITES: usize = 32;
const PARALLEL_SEGMENT_WRITE_RECORD_BUDGET: usize = 16_384;
/// Keep latency-sensitive online writes scalar; amortize the Rayon wave only
/// once catalog routing has enough independent vectors to pay for scheduling.
const PARALLEL_WRITE_ROUTING_MIN_ROWS: usize = 256;
/// Default decoded late-interaction Arrow-batch retention window. It is fixed,
/// byte-bounded, and shared across callers; the full corpus is never resident.
pub const DEFAULT_LATE_INTERACTION_BATCH_CACHE_BYTES: u64 = 64 * 1024 * 1024;
/// Collection-wide retained decoded WAL-run window.
///
/// The primary index and every named modality share this one fixed budget.
pub const DEFAULT_WAL_TAIL_CACHE_BYTES: u64 = 16 * 1024 * 1024;
/// Collection-wide cap admitted for one wave of immutable WAL-run decodes.
pub const DEFAULT_WAL_TAIL_DECODE_BYTES: u64 = 16 * 1024 * 1024;
const VERSION_SKIP_CURRENT_RECHECK_DELAY: Duration = Duration::from_millis(10);
const BM25_K1: f64 = 1.2;
const BM25_B: f64 = 0.75;

