fn positioned_catalog_assignment(manifest: &Manifest) -> Result<PositionedRouteAssignment> {
    let reference = manifest.logical_cell_catalog_ref.as_ref().ok_or_else(|| {
        BorsukError::InvalidStorage(
            "routed positioned modality is missing its catalog reference".to_string(),
        )
    })?;
    let checksum = blake3::Hash::from_hex(&reference.checksum).map_err(|error| {
        BorsukError::InvalidStorage(format!("positioned catalog checksum is invalid: {error}"))
    })?;
    PositionedRouteAssignment::catalog(*checksum.as_bytes(), reference.routing_epoch)
}

fn positioned_analyzer_assignment(
    schema_fingerprint: &str,
    modality: &str,
    descriptor: &[u8],
) -> Result<PositionedRouteAssignment> {
    let mut hasher = blake3::Hasher::new();
    for field in [
        b"borsuk-positioned-analyzer-authority-v1".as_slice(),
        schema_fingerprint.as_bytes(),
        modality.as_bytes(),
        descriptor,
    ] {
        let field_len = u64::try_from(field.len()).map_err(|_| {
            BorsukError::InvalidStorage(
                "positioned analyzer authority field exceeds u64".to_string(),
            )
        })?;
        hasher.update(&field_len.to_be_bytes());
        hasher.update(field);
    }
    PositionedRouteAssignment::analyzer(*hasher.finalize().as_bytes())
}

fn positioned_projection_metadata(name: &str, kind: VectorKind) -> Result<Vec<u8>> {
    let mut bytes = Vec::with_capacity(7 + name.len());
    bytes.extend_from_slice(POSITIONED_PROJECTION_MAGIC);
    bytes.push(match kind {
        VectorKind::Dense => 0,
        VectorKind::Sparse => 1,
        VectorKind::LateInteraction => 2,
    });
    bytes.extend_from_slice(
        &u16::try_from(name.len())
            .map_err(|_| BorsukError::InvalidStorage("named vector name is too long".to_string()))?
            .to_le_bytes(),
    );
    bytes.extend_from_slice(name.as_bytes());
    Ok(bytes)
}

fn positioned_projection_from_metadata(metadata: &[u8]) -> Result<Option<(VectorKind, &str)>> {
    if !metadata.starts_with(POSITIONED_PROJECTION_MAGIC) {
        return Ok(None);
    }
    if metadata.len() < 7 {
        return Err(BorsukError::InvalidStorage(
            "positioned named projection metadata is truncated".to_string(),
        ));
    }
    let kind = match metadata[4] {
        0 => VectorKind::Dense,
        1 => VectorKind::Sparse,
        2 => VectorKind::LateInteraction,
        _ => {
            return Err(BorsukError::InvalidStorage(
                "positioned named projection kind is invalid".to_string(),
            ));
        }
    };
    let len = usize::from(u16::from_le_bytes([metadata[5], metadata[6]]));
    let name = metadata.get(7..7 + len).ok_or_else(|| {
        BorsukError::InvalidStorage("positioned named projection metadata is truncated".to_string())
    })?;
    if metadata.len() != 7 + len {
        return Err(BorsukError::InvalidStorage(
            "positioned named projection metadata has trailing bytes".to_string(),
        ));
    }
    Ok(Some((
        kind,
        std::str::from_utf8(name).map_err(|error| {
            BorsukError::InvalidStorage(format!(
                "positioned projection name is invalid UTF-8: {error}"
            ))
        })?,
    )))
}

fn positioned_tombstone_projection_path(
    payload_path: &str,
    payload_checksum: &str,
    modality: &str,
) -> String {
    format!(
        "{payload_path}{POSITIONED_TOMBSTONE_PROJECTION_SEPARATOR}PTP1:{payload_checksum}:{}:{modality}",
        modality.len()
    )
}

fn positioned_tombstone_projection_from_path(path: &str) -> Option<(&str, &str, &str)> {
    let (payload_path, projection) = path.rsplit_once(POSITIONED_TOMBSTONE_PROJECTION_SEPARATOR)?;
    let projection = projection.strip_prefix("PTP1:")?;
    let (payload_checksum, rest) = projection.split_once(':')?;
    let (length, modality) = rest.split_once(':')?;
    (length.parse::<usize>().ok()? == modality.len()).then_some((
        payload_path,
        payload_checksum,
        modality,
    ))
}

#[derive(Debug)]
struct LateInteractionBatch {
    rows: HashMap<usize, Option<crate::LateInteractionVector>>,
}

fn decoded_late_interaction_batch_bytes(batch: &LateInteractionBatch) -> u64 {
    let bytes = std::mem::size_of::<LateInteractionBatch>()
        .saturating_add(batch.rows.capacity().saturating_mul(std::mem::size_of::<(
            usize,
            Option<crate::LateInteractionVector>,
        )>()))
        .saturating_add(
            batch
                .rows
                .values()
                .filter_map(Option::as_ref)
                .map(crate::LateInteractionVector::resident_bytes)
                .sum::<usize>(),
        );
    u64::try_from(bytes).unwrap_or(u64::MAX)
}

fn estimated_segment_decode_bytes(summary: &SegmentSummary) -> u64 {
    let dense_vectors = (summary.object_count as u64)
        .saturating_mul(summary.dimensions as u64)
        .saturating_mul(std::mem::size_of::<f32>() as u64);
    let record_headers =
        (summary.object_count as u64).saturating_mul(std::mem::size_of::<VectorRecord>() as u64);
    summary
        .size_bytes
        .saturating_add(summary.vector_size_bytes)
        .max(dense_vectors.saturating_add(record_headers))
        .max(1)
}

impl fmt::Debug for BorsukIndex {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("BorsukIndex")
            .field("storage", &self.storage)
            .field("manifest", &self.manifest)
            .field("named", &self.named.keys().collect::<Vec<_>>())
            .field("tokenizer", &self.tokenizer.fingerprint())
            .field("runtime_ram_budget_bytes", &self.runtime_ram_budget_bytes)
            .field("segment_cache", &self.segment_cache.get())
            .field(
                "retained_cache_bytes",
                &self
                    .read_runtime
                    .retained_pool
                    .as_ref()
                    .map(|pool| (pool.used_bytes(), pool.capacity_bytes(), pool.peak_bytes())),
            )
            .field(
                "transient_decode_bytes",
                &self
                    .read_runtime
                    .transient_admission
                    .as_ref()
                    .map(|gate| (gate.used_bytes(), gate.capacity_bytes(), gate.peak_bytes())),
            )
            .field(
                "resident_routing_summaries",
                &self.resident_routing_summaries.lock().map(|value| {
                    value
                        .as_ref()
                        .map(|(version, summaries)| (*version, summaries.len()))
                }),
            )
            .field(
                "coarse_quantizer",
                &self.coarse_quantizer.lock().map(|value| {
                    value
                        .as_ref()
                        .map(|(version, _, summaries)| (*version, summaries.len()))
                }),
            )
            .field("admission", &self.admission)
            .field("tombstone_cache", &self.tombstone_cache)
            .field("cell_wal_transactions", &self.cell_wal_snapshot.len())
            .finish()
    }
}

