#[derive(Debug, Clone, Default)]
struct PreparedPositionedModalitySnapshot {
    transactions: Vec<CommittedCellWalTransaction>,
    run_identities: BTreeSet<String>,
}

// Rust does not expose BTree node allocation sizes. Charge a conservative
// per-entry pointer/length allowance in addition to the inline key/value and
// every owned buffer capacity, so admission never treats tree bookkeeping as
// free memory.
const PREPARED_BTREE_ENTRY_OVERHEAD: usize = 4 * std::mem::size_of::<usize>();

fn prepared_run_dynamic_bytes(run: &PreparedCellWalRun) -> usize {
    run.transaction_id
        .capacity()
        .saturating_add(run.metadata.capacity())
        .saturating_add(run.path.capacity())
        .saturating_add(run.checksum.capacity())
}

fn prepared_transaction_resident_bytes(transaction: &CommittedCellWalTransaction) -> usize {
    std::mem::size_of::<CommittedCellWalTransaction>()
        .saturating_add(transaction.transaction_id.capacity())
        .saturating_add(transaction.descriptor_path.capacity())
        .saturating_add(transaction.descriptor_checksum.capacity())
        .saturating_add(transaction.metadata.capacity())
        .saturating_add(
            transaction
                .runs
                .capacity()
                .saturating_mul(std::mem::size_of::<PreparedCellWalRun>()),
        )
        .saturating_add(
            transaction
                .runs
                .iter()
                .map(prepared_run_dynamic_bytes)
                .fold(0_usize, usize::saturating_add),
        )
}

impl PreparedPositionedModalitySnapshot {
    fn resident_bytes(&self) -> usize {
        prepared_modality_resident_bytes(
            &self.transactions,
            self.transactions.capacity(),
            &self.run_identities,
        )
    }
}

fn prepared_modality_resident_bytes(
    transactions: &[CommittedCellWalTransaction],
    transaction_capacity: usize,
    run_identities: &BTreeSet<String>,
) -> usize {
    std::mem::size_of::<PreparedPositionedModalitySnapshot>()
        .saturating_add(
            transaction_capacity.saturating_mul(std::mem::size_of::<CommittedCellWalTransaction>()),
        )
        .saturating_add(
            transactions
                .iter()
                .map(prepared_transaction_resident_bytes)
                .map(|bytes| {
                    bytes.saturating_sub(std::mem::size_of::<CommittedCellWalTransaction>())
                })
                .fold(0_usize, usize::saturating_add),
        )
        .saturating_add(
            run_identities
                .iter()
                .map(|identity| {
                    std::mem::size_of::<String>()
                        .saturating_add(identity.capacity())
                        .saturating_add(PREPARED_BTREE_ENTRY_OVERHEAD)
                })
                .fold(0_usize, usize::saturating_add),
        )
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct AuthenticatedPrimaryRouteAuthority {
    catalog_checksum: String,
    routing_epoch: u64,
    strategy: CatalogRoutingStrategy,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct AuthenticatedPrimaryRoutePrefix {
    position: crate::CommitSourcePosition,
    cell_ordinals: Arc<[u32]>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct AuthenticatedRouteProjection {
    projection_kind: PositionedRouteProjectionKind,
    assignment: PositionedRouteAssignment,
    logical_row_count: u64,
    cell_ordinals: Arc<[u32]>,
    entity_token_offsets: Arc<[u32]>,
}

impl AuthenticatedRouteProjection {
    fn resident_bytes(&self) -> usize {
        std::mem::size_of::<Self>()
            .saturating_add(4 * std::mem::size_of::<usize>())
            .saturating_add(std::mem::size_of_val(self.cell_ordinals.as_ref()))
            .saturating_add(std::mem::size_of_val(self.entity_token_offsets.as_ref()))
    }
}

fn authenticated_route_projections(
    rows: &[PositionedRoutePlanRow],
) -> Result<BTreeMap<String, AuthenticatedRouteProjection>> {
    let mut projections = BTreeMap::new();
    for summary in rows.iter().filter(|row| row.record_id.is_none()) {
        let data = rows
            .iter()
            .filter(|row| row.modality == summary.modality && row.record_id.is_some())
            .collect::<Vec<_>>();
        let cell_ordinals = data
            .iter()
            .filter_map(|row| row.cell_ordinal)
            .collect::<Vec<_>>();
        if matches!(
            summary.projection_kind,
            PositionedRouteProjectionKind::Primary
                | PositionedRouteProjectionKind::Dense
                | PositionedRouteProjectionKind::LateInteraction
        ) && cell_ordinals.len() != data.len()
        {
            return Err(BorsukError::InvalidStorage(format!(
                "authenticated route projection `{}` lost a catalog cell",
                summary.modality
            )));
        }
        let mut entity_token_offsets = Vec::new();
        if summary.projection_kind == PositionedRouteProjectionKind::LateInteraction {
            entity_token_offsets.push(0_u32);
            let mut previous = None::<&[u8]>;
            for (row_index, row) in data.iter().enumerate() {
                let id = row.record_id.as_deref().expect("filtered route data row");
                if previous.is_some_and(|current| current != id) {
                    entity_token_offsets.push(u32::try_from(row_index).map_err(|_| {
                        BorsukError::InvalidStorage(
                            "late route projection row count exceeds u32".to_owned(),
                        )
                    })?);
                }
                previous = Some(id);
            }
            if !data.is_empty() {
                entity_token_offsets.push(u32::try_from(data.len()).map_err(|_| {
                    BorsukError::InvalidStorage(
                        "late route projection row count exceeds u32".to_owned(),
                    )
                })?);
            }
        }
        let projection = AuthenticatedRouteProjection {
            projection_kind: summary.projection_kind,
            assignment: summary.assignment.clone(),
            logical_row_count: summary.logical_row_count,
            cell_ordinals: Arc::from(cell_ordinals),
            entity_token_offsets: Arc::from(entity_token_offsets),
        };
        if projections
            .insert(summary.modality.clone(), projection)
            .is_some()
        {
            return Err(BorsukError::InvalidStorage(
                "authenticated route projections repeat a modality".to_owned(),
            ));
        }
    }
    Ok(projections)
}

