    #[test]
    fn snapshot_cache_build_is_single_flight_without_holding_mutex() {
        let cache: Mutex<Option<(u64, Arc<u64>)>> = Mutex::new(None);
        let inflight = Arc::new(InFlightReads::<u64>::default());
        let start = Arc::new(Barrier::new(2));
        let builds = Arc::new(AtomicUsize::new(0));
        let first_start = Arc::clone(&start);
        let first_builds = Arc::clone(&builds);
        let first_cache = &cache;
        let first_inflight = Arc::clone(&inflight);
        let first = thread::scope(|scope| {
            scope.spawn(move || {
                cached_snapshot(first_cache, &first_inflight, 7, "seven", || {
                    first_builds.fetch_add(1, AtomicOrdering::Relaxed);
                    first_start.wait();
                    Ok(11_u64)
                })
                .unwrap()
            });
            let second_start = Arc::clone(&start);
            let second_builds = Arc::clone(&builds);
            let second_cache = &cache;
            let second_inflight = Arc::clone(&inflight);
            scope.spawn(move || {
                cached_snapshot(second_cache, &second_inflight, 7, "seven", || {
                    second_builds.fetch_add(1, AtomicOrdering::Relaxed);
                    second_start.wait();
                    Ok(11_u64)
                })
                .unwrap()
            });
            // The leader reaches the barrier while the follower waits on the
            // same in-flight result; a cache mutex held during build would
            // deadlock the lookup, while duplicate builders would count twice.
            start.wait();
            Arc::new(11_u64)
        });
        assert_eq!(*first, 11);
        assert_eq!(builds.load(AtomicOrdering::Relaxed), 1);
    }

    #[test]
    fn resident_generation_cache_is_single_flight_bounded_and_arc_safe() {
        let cache = Arc::new(BoundedResidentCache::<u64>::new(2));
        let loads = Arc::new(AtomicUsize::new(0));
        thread::scope(|scope| {
            for _ in 0..2 {
                let cache = Arc::clone(&cache);
                let loads = Arc::clone(&loads);
                scope.spawn(move || {
                    let loaded = cache
                        .load("one", || {
                            loads.fetch_add(1, AtomicOrdering::Relaxed);
                            thread::sleep(Duration::from_millis(25));
                            Ok(1_u64)
                        })
                        .unwrap();
                    assert_eq!(*loaded, 1);
                });
            }
        });
        assert_eq!(loads.load(AtomicOrdering::Relaxed), 1);

        let pinned = cache.get("one").unwrap();
        let reclaimable = Arc::downgrade(&pinned);
        cache.insert("two".to_string(), Arc::new(2));
        cache.insert("three".to_string(), Arc::new(3));
        assert_eq!(cache.len(), 2);
        assert_eq!(*pinned, 1, "eviction invalidated a live snapshot pin");
        drop(pinned);
        assert!(
            reclaimable.upgrade().is_none(),
            "evicted and unpinned generation was not reclaimed"
        );
    }
    #[test]
    fn resident_v12_deadline_stops_before_descriptor_and_root_setup() {
        let dir = tempfile::tempdir().unwrap();
        let mut index = BorsukIndex::create(IndexConfig {
            uri: dir.path().to_string_lossy().into_owned(),
            metric: VectorMetric::Euclidean,
            dimensions: 8,
            segment_max_vectors: 16,
            ram_budget_bytes: None,
            text: false,
            named_vectors: BTreeMap::new(),
        })
        .unwrap();
        index
            .add(
                (0..128)
                    .map(|row| VectorRecord::new(format!("row-{row}"), vec![row as f32; 8]))
                    .collect(),
            )
            .unwrap();
        index.finish_bulk_load().unwrap();
        index.resident_global_codebooks.clear();
        index.resident_global_leaf_runs.clear();
        let requests_before = index.storage.request_counts();
        let started = Instant::now()
            .checked_sub(Duration::from_millis(10))
            .unwrap();

        let execution = index
            .search_resident_global_ann(
                &[0.0; 8],
                &SearchOptions::approx(1, LeafMode::SrhtPqScan)
                    .with_max_segments(4)
                    .with_max_latency_ms(1),
                false,
                started,
                &requests_before,
            )
            .unwrap()
            .unwrap();

        assert_eq!(
            execution.report.termination_reason,
            SearchTerminationReason::MaxLatency
        );
        assert_eq!(
            index.storage.request_counts().delta(&requests_before).gets,
            0,
            "expired V12 request performed descriptor/root setup I/O"
        );
    }

