    #[test]
    fn wal_tail_runtime_single_flights_overlapping_decodes_without_retention() {
        let runtime = Arc::new(WalTailRuntime::new(0, 1024));
        let loads = Arc::new(AtomicUsize::new(0));
        let callers = (0..4)
            .map(|_| {
                let runtime = Arc::clone(&runtime);
                let loads = Arc::clone(&loads);
                thread::spawn(move || {
                    runtime
                        .load_record_run("immutable-run", 128, || {
                            loads.fetch_add(1, Ordering::SeqCst);
                            thread::sleep(Duration::from_millis(50));
                            Ok(vec![VectorRecord::new("row", vec![1.0, 2.0])])
                        })
                        .unwrap()
                })
            })
            .collect::<Vec<_>>();
        let values = callers
            .into_iter()
            .map(|caller| caller.join().unwrap())
            .collect::<Vec<_>>();

        assert_eq!(loads.load(Ordering::SeqCst), 1);
        assert!(
            values
                .iter()
                .skip(1)
                .all(|value| Arc::ptr_eq(&values[0], value))
        );
        assert_eq!(runtime.resident_bytes(), 0);
    }

    #[test]
    fn wal_tail_runtime_retention_never_exceeds_its_collection_byte_cap() {
        let runtime = WalTailRuntime::new(1024, 1024);
        for ordinal in 0..64 {
            runtime
                .load_record_run(&format!("run-{ordinal}"), 128, || {
                    Ok(vec![VectorRecord::new(
                        format!("row-{ordinal}"),
                        vec![ordinal as f32; 8],
                    )])
                })
                .unwrap();
        }

        assert!(runtime.resident_bytes() <= 1024);
    }

    #[test]
    fn wal_point_lookup_reuses_one_generation_resolved_snapshot() {
        let directory = tempfile::tempdir().unwrap();
        let uri = directory.path().to_string_lossy().into_owned();
        let mut index = BorsukIndex::create(IndexConfig {
            uri,
            metric: VectorMetric::Euclidean,
            dimensions: 2,
            segment_max_vectors: 4,
            ram_budget_bytes: None,
            text: false,
            named_vectors: BTreeMap::new(),
        })
        .unwrap();
        index.wal_tail_runtime = Arc::new(WalTailRuntime::new(0, 1024 * 1024));
        index
            .put(vec![VectorRecord::new("row", vec![1.0, 2.0])])
            .unwrap();
        let pinned = index.clone();

        let first = pinned.live_wal_snapshot().unwrap();
        let first_dense = pinned.dense_live_wal_records(None).unwrap();
        for _ in 0..128 {
            assert_eq!(pinned.get_vector("row").unwrap(), Some(vec![1.0, 2.0]));
        }
        let reused = pinned.live_wal_snapshot().unwrap();
        assert!(Arc::ptr_eq(&first, &reused));
        assert!(Arc::ptr_eq(
            &first_dense,
            &pinned.dense_live_wal_records(None).unwrap()
        ));

        index
            .put(vec![VectorRecord::new("row", vec![3.0, 4.0])])
            .unwrap();
        let advanced = index.live_wal_snapshot().unwrap();
        assert!(!Arc::ptr_eq(&first, &advanced));
        assert_eq!(index.get_vector("row").unwrap(), Some(vec![3.0, 4.0]));

        assert_eq!(index.delete(["row"]).unwrap().ids_submitted, 1);
        let deleted = index.live_wal_snapshot().unwrap();
        assert!(!Arc::ptr_eq(&advanced, &deleted));
        assert_eq!(index.get_vector("row").unwrap(), None);

        // The pre-update clone remains pinned to its old frontier even though
        // both handles share the one-entry snapshot cache.
        assert_eq!(pinned.get_vector("row").unwrap(), Some(vec![1.0, 2.0]));
    }

    #[test]
    fn root_and_named_modalities_share_one_collection_read_runtime() {
        let directory = tempfile::tempdir().unwrap();
        let uri = directory.path().to_string_lossy().into_owned();
        let mut index = BorsukIndex::create(IndexConfig {
            uri: uri.clone(),
            metric: VectorMetric::Euclidean,
            dimensions: 2,
            segment_max_vectors: 4,
            ram_budget_bytes: None,
            text: false,
            named_vectors: BTreeMap::from([(
                "dense-child".to_string(),
                VectorSpec {
                    dimensions: 2,
                    metric: VectorMetric::Euclidean,
                    kind: VectorKind::Dense,
                    element_type: Default::default(),
                },
            )]),
        })
        .unwrap();
        let child = &index.named["dense-child"];
        assert!(Arc::ptr_eq(&index.read_runtime, &child.read_runtime));
        assert!(Arc::ptr_eq(
            &index.wal_tail_runtime,
            &child.wal_tail_runtime
        ));
        assert!(Arc::ptr_eq(
            &index.decoded_lexical_reads,
            &child.decoded_lexical_reads
        ));
        assert!(Arc::ptr_eq(&index.tombstone_cache, &child.tombstone_cache));
        assert!(Arc::ptr_eq(
            &index.vector_sidecar_indexes,
            &child.vector_sidecar_indexes
        ));
        assert!(Arc::ptr_eq(
            &index.late_interaction_sidecar_indexes,
            &child.late_interaction_sidecar_indexes
        ));
        assert!(Arc::ptr_eq(
            index.admission.as_ref().unwrap(),
            child.admission.as_ref().unwrap()
        ));
        assert!(Arc::ptr_eq(
            index.decode_admission.as_ref().unwrap(),
            child.decode_admission.as_ref().unwrap()
        ));
        index
            .add(vec![
                VectorRecord::new("a", vec![0.0, 0.0])
                    .with_named_vector("dense-child", vec![0.0, 0.0]),
                VectorRecord::new("b", vec![1.0, 0.0])
                    .with_named_vector("dense-child", vec![1.0, 0.0]),
            ])
            .unwrap();
        index.flush().unwrap();
        drop(index);

        let reopened = BorsukIndex::open(&uri).unwrap();
        let child = &reopened.named["dense-child"];
        assert!(Arc::ptr_eq(&reopened.read_runtime, &child.read_runtime));
        assert!(Arc::ptr_eq(
            &reopened.wal_tail_runtime,
            &child.wal_tail_runtime
        ));
        assert!(Arc::ptr_eq(
            reopened.lexical_admission.as_ref().unwrap(),
            child.lexical_admission.as_ref().unwrap()
        ));
        assert!(Arc::ptr_eq(
            reopened
                .read_runtime
                .retained_pool
                .as_ref()
                .expect("finite default budget has a retained pool"),
            child
                .read_runtime
                .retained_pool
                .as_ref()
                .expect("child shares the retained pool"),
        ));
        reopened
            .search_with_report(
                &[0.0, 0.0],
                SearchOptions::exact(1).with_vector_name("dense-child"),
            )
            .unwrap();
        let transient = reopened
            .read_runtime
            .transient_admission
            .as_ref()
            .expect("finite default budget has transient admission");
        assert!(transient.peak_bytes() > 0);
        assert!(transient.peak_bytes() <= transient.capacity_bytes());
    }

