    #[test]
    fn explicit_flush_materializes_and_fences_positioned_transactions() {
        let directory = tempfile::tempdir().unwrap();
        let mut index = BorsukIndex::create(IndexConfig {
            uri: directory.path().to_string_lossy().into_owned(),
            metric: VectorMetric::Euclidean,
            dimensions: 2,
            segment_max_vectors: 4,
            ram_budget_bytes: None,
            text: false,
            named_vectors: BTreeMap::new(),
        })
        .unwrap();

        index
            .add(vec![VectorRecord::new("tail", vec![0.0, 0.0])])
            .unwrap();
        assert_eq!(index.cell_wal_snapshot.len(), 1);
        assert!(index.active_segment_summaries().unwrap().is_empty());
        let transaction_id = index.cell_wal_snapshot[0].transaction_id.clone();
        let positioned_run_identities = index.cell_wal_snapshot[0]
            .runs
            .iter()
            .map(cell_wal_run_identity)
            .collect::<BTreeSet<_>>();
        let generation_before_flush = index
            .collection_snapshot
            .as_ref()
            .unwrap()
            .snapshot
            .generation;
        let positioned_before_flush = index
            .positioned_log
            .as_ref()
            .unwrap()
            .reader()
            .snapshot_for_collection_generation(generation_before_flush)
            .unwrap();
        assert!(
            positioned_before_flush
                .transactions
                .iter()
                .any(|transaction| transaction.transaction_id == transaction_id)
        );

        index.flush().unwrap();

        assert!(index.cell_wal_snapshot.is_empty());
        assert_eq!(index.active_segment_summaries().unwrap().len(), 1);
        assert_eq!(
            index.manifest.cell_wal_consumed_runs, positioned_run_identities,
            "the materialized manifest must fence every run still authorized by the positioned head"
        );
        let positioned_after_flush = index
            .positioned_log
            .as_ref()
            .unwrap()
            .reader()
            .snapshot_for_collection_generation(
                index
                    .collection_snapshot
                    .as_ref()
                    .unwrap()
                    .snapshot
                    .generation,
            )
            .unwrap();
        assert!(
            positioned_after_flush.transactions.is_empty(),
            "the current materialized generation must not rescan checkpointed transactions"
        );
        let positioned_for_pinned_reader = index
            .positioned_log
            .as_ref()
            .unwrap()
            .reader()
            .snapshot_for_collection_generation(generation_before_flush)
            .unwrap();
        assert!(
            positioned_for_pinned_reader
                .transactions
                .iter()
                .any(|transaction| transaction.transaction_id == transaction_id),
            "the bounded recent receipt must preserve the pre-flush pinned generation"
        );
        assert_eq!(
            index
                .search_ids(&[0.0, 0.0], SearchOptions::exact(1))
                .unwrap(),
            ["tail"]
        );
    }

    #[test]
    fn positioned_route_validation_rejects_substitution_mismatch_and_payload_cardinality() {
        let directory = tempfile::tempdir().unwrap();
        let mut index = BorsukIndex::create(IndexConfig {
            uri: directory.path().to_string_lossy().into_owned(),
            metric: VectorMetric::Euclidean,
            dimensions: 2,
            segment_max_vectors: 4,
            ram_budget_bytes: None,
            text: true,
            named_vectors: BTreeMap::new(),
        })
        .unwrap();
        index
            .add(vec![
                VectorRecord::new("routed", vec![1.0, 0.0]).with_text("alpha beta"),
            ])
            .unwrap();

        let snapshot = index
            .positioned_log
            .as_ref()
            .unwrap()
            .reader()
            .snapshot()
            .unwrap();
        let envelope = snapshot.transactions.last().unwrap().clone();
        let named_manifests = BTreeMap::new();
        let loaded = index
            .validate_positioned_route_plan_envelope(&envelope, &index.manifest, &named_manifests)
            .unwrap();
        let primary_payload = envelope
            .payloads
            .iter()
            .find(|payload| payload.modality == PositionedMutationModality::PrimaryDense)
            .unwrap();
        let directory_payload = envelope
            .payloads
            .iter()
            .find(|payload| {
                payload.modality == PositionedMutationModality::IdDirectory
                    && payload.role.starts_with('{')
            })
            .unwrap();
        let route_payload = envelope
            .payloads
            .iter()
            .find(|payload| payload.modality == PositionedMutationModality::RoutePlan)
            .unwrap();
        let primary_records = positioned_wal_records_from_table(
            loaded.get(&primary_payload.path).unwrap().clone(),
            &primary_payload.path,
        )
        .unwrap();
        let id_directory = cell_wal_id_directory_from_slice(
            loaded.get(&directory_payload.path).unwrap(),
            &directory_payload.path,
        )
        .unwrap();
        let rows =
            positioned_route_plan_from_parquet(loaded.get(&route_payload.path).unwrap()).unwrap();
        let summary_stamp = MutationStamp::new(
            MutationVersion::from_parts(envelope.min_stamp.hlc, envelope.min_stamp.writer),
            envelope.min_stamp.digest,
        );
        let rejects = |candidate: &[PositionedRoutePlanRow]| {
            index
                .validate_positioned_route_plan_rows(
                    &index.manifest,
                    &named_manifests,
                    &primary_records,
                    &id_directory,
                    summary_stamp,
                    candidate,
                )
                .is_err()
        };

        let mut substituted_catalog = rows.clone();
        for row in substituted_catalog
            .iter_mut()
            .filter(|row| row.modality == "primary")
        {
            row.assignment.checksum = [0x55; 32];
        }
        assert!(rejects(&substituted_catalog));

        let mut substituted_analyzer = rows.clone();
        for row in substituted_analyzer
            .iter_mut()
            .filter(|row| row.modality == HYBRID_TEXT_MODALITY)
        {
            row.assignment.checksum = [0x66; 32];
        }
        assert!(rejects(&substituted_analyzer));

        let mut primary_owner_mismatch = rows.clone();
        primary_owner_mismatch
            .iter_mut()
            .find(|row| row.modality == "primary" && row.record_id.is_some())
            .unwrap()
            .cell_ordinal = Some(u32::MAX);
        assert!(rejects(&primary_owner_mismatch));

        let mut primary_payload_mismatch = primary_records.clone();
        primary_payload_mismatch[0].2 = u32::MAX;
        assert!(
            index
                .validate_positioned_route_plan_rows(
                    &index.manifest,
                    &named_manifests,
                    &primary_payload_mismatch,
                    &id_directory,
                    summary_stamp,
                    &rows,
                )
                .is_err()
        );

        let mut directory_mismatch = id_directory.clone();
        directory_mismatch[0].owner =
            LogicalCellId::new(directory_mismatch[0].owner.routing_epoch, u32::MAX);
        assert!(
            index
                .validate_positioned_route_plan_rows(
                    &index.manifest,
                    &named_manifests,
                    &primary_records,
                    &directory_mismatch,
                    summary_stamp,
                    &rows,
                )
                .is_err()
        );

        let mut id_mismatch = rows.clone();
        id_mismatch
            .iter_mut()
            .find(|row| row.modality == "primary" && row.record_id.is_some())
            .unwrap()
            .record_id = Some(b"substituted-id".to_vec());
        assert!(rejects(&id_mismatch));

        let mut missing = envelope.clone();
        missing
            .payloads
            .retain(|payload| payload.modality != PositionedMutationModality::RoutePlan);
        assert!(
            index
                .validate_positioned_route_plan_envelope(
                    &missing,
                    &index.manifest,
                    &named_manifests,
                )
                .is_err()
        );

        let mut extra = envelope.clone();
        extra.payloads.push(route_payload.clone());
        assert!(
            index
                .validate_positioned_route_plan_envelope(&extra, &index.manifest, &named_manifests,)
                .is_err()
        );

        let mut obsolete_role_authority = envelope.clone();
        let role = &mut obsolete_role_authority
            .payloads
            .iter_mut()
            .find(|payload| payload.modality == PositionedMutationModality::PrimaryDense)
            .unwrap()
            .role;
        let mut role_json = serde_json::from_str::<serde_json::Value>(role).unwrap();
        role_json["routing_epoch"] = serde_json::json!(1);
        role_json["cell_ordinal"] = serde_json::json!(0);
        *role = serde_json::to_string(&role_json).unwrap();
        let obsolete_error = index
            .validate_positioned_route_plan_envelope(
                &obsolete_role_authority,
                &index.manifest,
                &named_manifests,
            )
            .unwrap_err()
            .to_string();
        assert!(obsolete_error.contains("unknown field"), "{obsolete_error}");

        let mut non_parquet = envelope.clone();
        non_parquet
            .payloads
            .iter_mut()
            .find(|payload| payload.modality == PositionedMutationModality::PrimaryDense)
            .unwrap()
            .format = PositionedPayloadFormat::ArrowIpc;
        let format_error = index
            .validate_positioned_route_plan_envelope(
                &non_parquet,
                &index.manifest,
                &named_manifests,
            )
            .unwrap_err()
            .to_string();
        assert!(
            format_error.contains("must use standard Parquet"),
            "{format_error}"
        );

        let mut substituted_modality = envelope;
        substituted_modality
            .payloads
            .iter_mut()
            .find(|payload| payload.modality == PositionedMutationModality::PrimaryDense)
            .unwrap()
            .modality = PositionedMutationModality::NamedDense;
        assert!(
            index
                .validate_positioned_route_plan_envelope(
                    &substituted_modality,
                    &index.manifest,
                    &named_manifests,
                )
                .is_err()
        );
    }

    fn encoded_staged_source_min(runs: &[StagedPositionedRun]) -> MutationStamp {
        runs.iter()
            .filter(|run| run.modality == PRIMARY_MODALITY)
            .map(|run| {
                let metadata = positioned_payload_metadata(
                    &run.input.bytes,
                    PositionedPayloadFormat::Parquet,
                    run.input.record_count as u64,
                )
                .unwrap();
                MutationStamp::new(
                    MutationVersion::from_parts(metadata.min_stamp.hlc, metadata.min_stamp.writer),
                    metadata.min_stamp.digest,
                )
            })
            .reduce(|current, candidate| {
                if candidate.version() < current.version() {
                    candidate
                } else {
                    current
                }
            })
            .expect("a staged primary source is nonempty")
    }

    #[test]
    fn positioned_route_plan_reuses_staged_facts_without_decoding_wal_payloads() {
        let directory = tempfile::tempdir().unwrap();
        let mut index = BorsukIndex::create(IndexConfig {
            uri: directory.path().to_string_lossy().into_owned(),
            metric: VectorMetric::Euclidean,
            dimensions: 2,
            segment_max_vectors: 4,
            ram_budget_bytes: None,
            text: false,
            named_vectors: BTreeMap::new(),
        })
        .unwrap();
        index.begin_collection_transaction().unwrap();
        index
            .add_collection_records(vec![VectorRecord::new("staged", vec![1.0, 2.0])])
            .unwrap();
        let duplicate_source = index
            .add_collection_records(vec![VectorRecord::new("second", vec![2.0, 3.0])])
            .unwrap_err();
        assert!(
            duplicate_source
                .to_string()
                .contains("multiple primary route sources"),
            "{duplicate_source}"
        );

        let transaction = index
            .active_collection_transaction
            .as_ref()
            .unwrap()
            .clone();
        let route_source = transaction
            .positioned_route_source
            .lock()
            .unwrap_or_else(|error| error.into_inner())
            .take()
            .expect("primary staging retains route facts");
        let expected_stamp = route_source.summary_stamp().unwrap();
        assert_eq!(route_source.primary_records.len(), 1);
        assert_eq!(route_source.id_directory.len(), 1);
        let runs = transaction
            .positioned
            .lock()
            .unwrap_or_else(|error| error.into_inner())
            .clone();
        assert_eq!(expected_stamp, encoded_staged_source_min(&runs));
        let mut batch = CanonicalMutationBatch {
            transaction_id: transaction.id,
            schema_fingerprint: transaction.schema_fingerprint,
            runs,
            metadata: transaction
                .positioned_metadata
                .lock()
                .unwrap_or_else(|error| error.into_inner())
                .clone(),
            route_source: Some(route_source),
        };

        let (stamp, rows) = index.positioned_route_plan_for_batch(&batch).unwrap();
        assert_eq!(stamp, expected_stamp);
        assert_eq!(rows.len(), 2, "one primary summary plus one routed row");
        let route_source = batch.route_source.take().unwrap();
        let missing = index.positioned_route_plan_for_batch(&batch).unwrap_err();
        assert!(
            missing
                .to_string()
                .contains("missing its staged route source")
        );
        batch.route_source = Some(route_source);
        let directory_run = batch
            .runs
            .iter_mut()
            .find(|run| run.input.kind == CellWalRunKind::IdDirectory)
            .unwrap();
        directory_run.input.record_count += 1;
        let mismatch = index.positioned_route_plan_for_batch(&batch).unwrap_err();
        assert!(mismatch.to_string().contains("payload cardinality"));
        batch
            .runs
            .iter_mut()
            .find(|run| run.input.kind == CellWalRunKind::IdDirectory)
            .unwrap()
            .input
            .record_count -= 1;
        let duplicate_record_run = batch
            .runs
            .iter()
            .find(|run| run.input.kind == CellWalRunKind::Records)
            .unwrap()
            .clone();
        batch.runs.push(duplicate_record_run);
        let duplicate = index.positioned_route_plan_for_batch(&batch).unwrap_err();
        assert!(
            duplicate
                .to_string()
                .contains("multiple primary record payloads")
        );
        batch.runs.pop();
        for run in &mut batch.runs {
            if matches!(
                run.input.kind,
                CellWalRunKind::Records | CellWalRunKind::IdDirectory
            ) {
                run.input.bytes = b"deliberately-not-parquet".to_vec();
            }
        }
        let requests_before = index.storage.request_counts();
        let error = index.append_positioned_mutation(batch).unwrap_err();
        assert!(error.to_string().contains("Parquet"), "{error}");
        assert_eq!(
            index
                .storage
                .request_counts()
                .delta(&requests_before)
                .total(),
            0,
            "byte-level validation must still reject corruption before upload"
        );
        index.clear_collection_transaction(false);
    }

