    #[test]
    fn incremental_delta_is_deterministic_and_rejects_gapped_base_extension() {
        let (_directory, mut index) = all_modality_test_index();
        let transaction_ids = (0_u64..)
            .map(|ordinal| format!("materialization-gap-{ordinal}"))
            .filter(|transaction_id| {
                blake3::hash(transaction_id.as_bytes()).as_bytes()[0]
                    .is_multiple_of(crate::positioned_log::SOURCE_SHARD_COUNT)
            })
            .take(3)
            .collect::<Vec<_>>();
        let append = |index: &mut BorsukIndex, transaction_id: &str, record: VectorRecord| {
            index.begin_collection_transaction().unwrap();
            index
                .active_collection_transaction
                .as_mut()
                .unwrap()
                .id
                .clone_from(&transaction_id.to_owned());
            let result = index.add_collection_records(vec![record]);
            index.finish_collection_transaction(result).unwrap();
        };
        append(
            &mut index,
            &transaction_ids[0],
            all_modality_record("first", 1.0),
        );
        index.reload_positioned_snapshot().unwrap();
        let first_position = index.cell_wal_snapshot[0].source_position.unwrap();
        let (primary_codebook, named_codebooks) = all_modality_test_codebooks(&index);
        let first = index
            .build_unwired_all_modality_delta(
                &positioned_coverage([first_position]),
                &primary_codebook,
                &named_codebooks,
                None,
                &MaterializationLevelAuthority::default(),
            )
            .unwrap();
        let anchor = first.chain_anchor().clone();

        append(
            &mut index,
            &transaction_ids[1],
            all_modality_record("second", 2.0),
        );
        append(
            &mut index,
            &transaction_ids[2],
            all_modality_record("third", 3.0),
        );
        index.reload_positioned_snapshot().unwrap();
        let mut later = index
            .cell_wal_snapshot
            .iter()
            .map(|transaction| transaction.source_position.unwrap())
            .filter(|position| *position != first_position)
            .collect::<Vec<_>>();
        later.sort_unstable();
        assert_eq!(first_position.shard, later[0].shard);
        assert_eq!(later[0].shard, later[1].shard);
        assert_eq!(later[0].sequence, first_position.sequence + 1);
        assert_eq!(later[1].sequence, later[0].sequence + 1);
        let (primary_codebook, named_codebooks) = all_modality_test_codebooks(&index);
        let second_a = index
            .build_unwired_all_modality_delta(
                &positioned_coverage([later[0]]),
                &primary_codebook,
                &named_codebooks,
                Some(&anchor),
                &MaterializationLevelAuthority::default(),
            )
            .unwrap();
        let second_b = index
            .build_unwired_all_modality_delta(
                &positioned_coverage([later[0]]),
                &primary_codebook,
                &named_codebooks,
                Some(&anchor),
                &MaterializationLevelAuthority::default(),
            )
            .unwrap();
        assert_eq!(second_a.new_roster(), second_b.new_roster());
        assert_eq!(
            second_a.row_bundle_delta_root(),
            second_b.row_bundle_delta_root()
        );
        assert_eq!(second_a.chain_anchor(), second_b.chain_anchor());

        let error = index
            .build_unwired_all_modality_delta(
                &positioned_coverage([later[1]]),
                &primary_codebook,
                &named_codebooks,
                Some(&anchor),
                &MaterializationLevelAuthority::default(),
            )
            .unwrap_err()
            .to_string();
        assert!(
            error.contains("gap") || error.contains("contiguous"),
            "{error}"
        );
    }

    #[test]
    fn incremental_primary_dense_candidate_uses_authenticated_route_prefix_not_legacy_cell() {
        let directory = tempfile::tempdir().unwrap();
        let mut index = BorsukIndex::create_with_logical_cell_catalog(
            IndexConfig {
                uri: directory.path().to_string_lossy().into_owned(),
                metric: VectorMetric::Euclidean,
                dimensions: 2,
                segment_max_vectors: 64,
                ram_budget_bytes: None,
                text: false,
                named_vectors: BTreeMap::new(),
            },
            vec![vec![0.0, 0.0], vec![10.0, 0.0], vec![20.0, 0.0]],
        )
        .unwrap();
        index
            .add(vec![
                VectorRecord::new("cell-2", vec![20.0, 0.0]),
                VectorRecord::new("cell-1", vec![10.0, 0.0]),
            ])
            .unwrap();
        index.reload_positioned_snapshot().unwrap();
        let position = index.cell_wal_snapshot[0].source_position.unwrap();
        for run in index
            .cell_wal_snapshot
            .iter_mut()
            .flat_map(|transaction| &mut transaction.runs)
        {
            run.cell = LogicalCellId::new(index.manifest.routing_epoch, u32::MAX);
        }
        let coverage = positioned_coverage([position]);
        let codebook = write_test_catalog_codebook(&index);
        let before_manifest = serde_json::to_value(&index.manifest.global_ann_ref).unwrap();
        let candidate = index
            .build_unwired_primary_dense_candidate(&coverage, &codebook, &[])
            .unwrap();

        assert_eq!(
            candidate.codebook().descriptor_checksum(),
            codebook.descriptor_checksum()
        );
        assert_eq!(
            serde_json::to_value(&index.manifest.global_ann_ref).unwrap(),
            before_manifest
        );
        assert_eq!(candidate.source_ranges(), &coverage);
        assert_eq!(
            candidate
                .watermarks()
                .sequence(position.source_epoch, position.shard),
            Some(position.sequence)
        );
        assert!(candidate.carried_runs().is_empty());
        let run = candidate.new_run().unwrap();
        let root = index
            .storage
            .read_bytes_with_cache_status_and_checksum(
                run.directory().path(),
                run.directory().checksum(),
            )
            .unwrap()
            .bytes;
        let directory = crate::global_leaf::decode_global_leaf_run_directory(
            run.codebook_checksum(),
            &root,
            |shard| {
                Ok(index
                    .storage
                    .read_bytes_with_cache_status_and_checksum(&shard.path, &shard.checksum)?
                    .bytes
                    .to_vec())
            },
        )
        .unwrap();
        assert_eq!(
            directory
                .pages
                .iter()
                .map(|page| page.cell_index)
                .collect::<BTreeSet<_>>(),
            BTreeSet::from([1_u32, 2])
        );

        assert!(candidate.roster().iter().any(|artifact| {
            artifact.role == GlobalLeafArtifactRole::CodebookDescriptor
                && artifact.path == codebook.descriptor_path()
        }));
        assert!(
            candidate
                .roster()
                .iter()
                .any(|artifact| artifact.role == GlobalLeafArtifactRole::LeafDirectoryRoot)
        );
        assert!(
            candidate
                .roster()
                .iter()
                .any(|artifact| artifact.role == GlobalLeafArtifactRole::LeafBundle)
        );
        assert!(
            candidate
                .roster()
                .iter()
                .any(|artifact| artifact.role == GlobalLeafArtifactRole::LeafCodePlane)
        );
        for artifact in candidate.roster() {
            let bytes = match artifact.range.clone() {
                Some(range) => index.storage.read_range(&artifact.path, range).unwrap(),
                None => {
                    index
                        .storage
                        .read_bytes_with_cache_status_and_checksum(
                            &artifact.path,
                            &artifact.checksum,
                        )
                        .unwrap()
                        .bytes
                }
            };
            assert_eq!(bytes.len() as u64, artifact.encoded_bytes);
            assert_eq!(blake3::hash(&bytes).to_hex().to_string(), artifact.checksum);
        }
    }

