    #[test]
    fn global_leaf_pages_encode_the_stored_physical_centroid_after_final_fitting() {
        let training = vec![
            vec![0.0, 0.0],
            vec![1.0, 3.0],
            vec![2.0, 4.0],
            vec![3.0, 5.0],
        ];
        let quantizer = GlobalScanQuantizer::from(
            RotatedProductQuantizer::fit(
                ProductQuantizerConfig {
                    rotation: crate::rotated_product_quantizer::ProductRotation::Identity,
                    seed: 7,
                    dimensions: 2,
                    subspaces: 1,
                    centroids: 2,
                    sample_limit: training.len(),
                    iterations: 2,
                },
                &training,
            )
            .unwrap(),
        );
        let exact_rows = [[1.0_f32, 3.0_f32], [3.0_f32, 5.0_f32]];
        let mut bytes = Vec::new();
        for exact in &exact_rows {
            bytes.extend_from_slice(&quantizer.encode(exact).unwrap());
        }
        let mut pending = vec![PendingGlobalPqChunk {
            cell_index: 9,
            chunk: crate::global_pq_sidecar::GlobalPqChunkBytes {
                bytes,
                exact_bytes: exact_rows
                    .into_iter()
                    .flatten()
                    .flat_map(f32::to_le_bytes)
                    .collect(),
                identities: vec![
                    (
                        RecordId::from("a"),
                        MutationStamp::new(MutationVersion::from_parts(1, [1; 16]), [2; 32]),
                    ),
                    (
                        RecordId::from("b"),
                        MutationStamp::new(MutationVersion::from_parts(2, [3; 16]), [4; 32]),
                    ),
                ],
                rows: 2,
            },
        }];

        let pages = build_global_leaf_pages(
            &mut pending,
            &mut BTreeMap::new(),
            quantizer.code_bytes_per_vector(),
            true,
            2,
            crate::VectorElementType::Float32,
            false,
            &quantizer,
        )
        .unwrap();

        assert_eq!(pages.len(), 1);
        assert_eq!(pages[0].cell_index, 9);
        assert_eq!(pages[0].leaf_ordinal, 0);
        assert_eq!(pages[0].rows.len(), 2);
        assert!(pending[0].chunk.bytes.is_empty());
        assert!(pages[0].rows[0].code.shares_backing(&pages[0].rows[1].code));
        assert_eq!(
            pages[0].centroid_code,
            quantizer.encode(&[2.0, 4.0]).unwrap()
        );
        assert_eq!(
            pages[0]
                .rows
                .iter()
                .flat_map(|row| row.exact.iter().copied())
                .collect::<Vec<_>>(),
            exact_rows
                .into_iter()
                .flatten()
                .flat_map(f32::to_le_bytes)
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn global_leaf_pages_continue_ordinals_across_spool_chunks_for_one_cell() {
        let training = vec![vec![0.0, 0.0], vec![1.0, 1.0]];
        let quantizer = GlobalScanQuantizer::from(
            RotatedProductQuantizer::fit(
                ProductQuantizerConfig {
                    rotation: crate::rotated_product_quantizer::ProductRotation::Identity,
                    seed: 11,
                    dimensions: 2,
                    subspaces: 1,
                    centroids: 2,
                    sample_limit: training.len(),
                    iterations: 2,
                },
                &training,
            )
            .unwrap(),
        );
        let chunk = |id: &str, version: u64| {
            let vector = [version as f32, version as f32];
            PendingGlobalPqChunk {
                cell_index: 9,
                chunk: crate::global_pq_sidecar::GlobalPqChunkBytes {
                    bytes: quantizer.encode(&vector).unwrap(),
                    exact_bytes: vector.into_iter().flat_map(f32::to_le_bytes).collect(),
                    identities: vec![(
                        RecordId::from(id),
                        MutationStamp::new(
                            MutationVersion::from_parts(version, [version as u8; 16]),
                            [version as u8 + 1; 32],
                        ),
                    )],
                    rows: 1,
                },
            }
        };
        let mut next_leaf = BTreeMap::new();
        let mut first = [chunk("first", 1)];
        let first = build_global_leaf_pages(
            &mut first,
            &mut next_leaf,
            quantizer.code_bytes_per_vector(),
            true,
            2,
            crate::VectorElementType::Float32,
            false,
            &quantizer,
        )
        .unwrap();
        let mut second = [chunk("second", 2)];
        let second = build_global_leaf_pages(
            &mut second,
            &mut next_leaf,
            quantizer.code_bytes_per_vector(),
            true,
            2,
            crate::VectorElementType::Float32,
            false,
            &quantizer,
        )
        .unwrap();

        assert_eq!(first[0].leaf_ordinal, 0);
        assert_eq!(second[0].leaf_ordinal, 1);
        assert_eq!(next_leaf.get(&9), Some(&2));
    }
