    #[test]
    fn resident_global_v14_rejects_corrupt_codebook_root_and_card_group_objects() {
        fn finished_index() -> (tempfile::TempDir, BorsukIndex) {
            let dir = tempfile::tempdir().unwrap();
            let mut index = BorsukIndex::create(IndexConfig {
                uri: dir.path().to_string_lossy().into_owned(),
                metric: VectorMetric::Euclidean,
                dimensions: 8,
                segment_max_vectors: 256,
                ram_budget_bytes: None,
                text: false,
                named_vectors: Default::default(),
            })
            .unwrap();
            index
                .add(
                    (0..128)
                        .map(|row| VectorRecord::new(format!("row-{row}"), vec![row as f32; 8]))
                        .collect(),
                )
                .unwrap();
            index.finish_bulk_load().unwrap();
            (dir, index)
        }

        let (codebook_dir, codebook_index) = finished_index();
        let codebook_path = codebook_index
            .manifest
            .global_cell_card_ann_ref
            .as_ref()
            .unwrap()
            .codebook()
            .descriptor_path()
            .to_string();
        let mut codebook_bytes = codebook_index
            .storage
            .read_bytes_with_cache_status(&codebook_path)
            .unwrap()
            .bytes;
        codebook_bytes[0] ^= 1;
        codebook_index
            .storage
            .write_bytes(&codebook_path, &codebook_bytes)
            .unwrap();
        drop(codebook_index);
        let error = BorsukIndex::open(codebook_dir.path().to_string_lossy().as_ref()).unwrap_err();
        assert!(error.to_string().contains("checksum"), "{error}");

        let (root_dir, root_index) = finished_index();
        let root_path = root_index
            .manifest
            .global_cell_card_ann_ref
            .as_ref()
            .unwrap()
            .root_path()
            .to_string();
        let mut root_bytes = root_index
            .storage
            .read_bytes_with_cache_status(&root_path)
            .unwrap()
            .bytes;
        root_bytes[0] ^= 1;
        root_index
            .storage
            .write_bytes(&root_path, &root_bytes)
            .unwrap();
        drop(root_index);
        let error = BorsukIndex::open(root_dir.path().to_string_lossy().as_ref()).unwrap_err();
        assert!(error.to_string().contains("checksum"), "{error}");

        let (_group_dir, group_index) = finished_index();
        let root = group_index
            .resident_global_ann_pins
            .as_ref()
            .and_then(|pins| pins.cell_card_root.as_ref())
            .unwrap()
            .clone();
        let (group, head) = root.head_ref(0).unwrap();
        let mut group_bytes = group_index
            .storage
            .read_bytes_with_cache_status(&group.path)
            .unwrap()
            .bytes;
        group_bytes[usize::try_from(head.offset).unwrap()] ^= 1;
        group_index
            .storage
            .write_bytes(&group.path, &group_bytes)
            .unwrap();
        let error = group_index
            .search_with_report(
                &[7.0; 8],
                SearchOptions::approx(3, LeafMode::SrhtPqScan)
                    .with_max_segments(4)
                    .with_max_candidates_per_segment(64),
            )
            .unwrap_err();
        assert!(error.to_string().contains("checksum"), "{error}");
    }

    #[test]
    fn resident_global_v12_preload_authenticates_every_shard_before_retaining_root_only() {
        let (_directory, index) = build_finished_resident_global_v12_index();
        let page_count = crate::global_leaf::GLOBAL_LEAF_DIRECTORY_SHARD_PAGES + 1;
        let pages = (0..page_count)
            .map(|ordinal| crate::global_leaf::GlobalLeafPageRef {
                cell_index: 7,
                leaf_ordinal: ordinal as u32,
                bundle_index: 0,
                batch_offset: 16_384 + ordinal as u64 * 1536,
                metadata_bytes: 512,
                body_bytes: 1024,
                batch_bytes: 1536,
                code_offset: 64 + ordinal as u64 * 2,
                code_bytes: 2,
                code_checksum: [(ordinal % 251) as u8; 32],
                rows: 1,
                partial_run_count: 0,
                checksum: [(ordinal % 251) as u8; 32],
                centroid_code: vec![7, (ordinal % 251) as u8].into_boxed_slice(),
                exact_blocks: vec![crate::global_leaf::GlobalLeafExactBlockRef {
                    first_row: 0,
                    rows: 1,
                    batch_offset: 16_384 + ordinal as u64 * 1536,
                    metadata_bytes: 512,
                    body_bytes: 1024,
                    batch_bytes: 1536,
                    checksum: [(ordinal % 251) as u8; 32],
                }]
                .into_boxed_slice(),
            })
            .collect::<Vec<_>>();
        let bundles = vec![crate::global_leaf::GlobalLeafBundleRef {
            path: "global-leaf/bundles/preload-auth.arrow".to_owned(),
            checksum: [9; 32],
            encoded_bytes: 16 * 1024 * 1024,
            code_plane_offset: 64,
            code_plane_bytes: page_count as u64 * 2,
            code_plane_checksum: [10; 32],
        }];
        let encoded =
            crate::global_leaf::encode_global_leaf_run_directory("11aa", &pages, &bundles).unwrap();
        assert_eq!(encoded.shards.len(), 2);
        let decoded = crate::global_leaf::decode_global_leaf_run_directory(
            "11aa",
            &encoded.root,
            |reference| {
                Ok(encoded
                    .shards
                    .iter()
                    .find(|shard| shard.reference.path == reference.path)
                    .unwrap()
                    .bytes
                    .clone())
            },
        )
        .unwrap();
        let expected_resident_bytes = decoded.resident_bytes() as u64;
        let root_path = "global-leaf/v12/directories/preload-auth-root.parquet";
        index.storage.write_bytes(root_path, &encoded.root).unwrap();
        for shard in &encoded.shards {
            index
                .storage
                .write_bytes(&shard.reference.path, &shard.bytes)
                .unwrap();
        }
        let root_checksum = blake3::hash(&encoded.root).to_hex().to_string();
        let directory = crate::global_leaf_run::GlobalLeafDirectoryRef::new(
            root_path.to_owned(),
            root_checksum,
            encoded.root.len() as u64,
            encoded.directory_object_count().unwrap(),
        );
        let encoded_bytes = bundles[0]
            .encoded_bytes
            .saturating_add(encoded.root.len() as u64)
            .saturating_add(
                encoded
                    .shards
                    .iter()
                    .map(|shard| shard.bytes.len() as u64)
                    .sum::<u64>(),
            );
        let stamp = MutationStamp::new(MutationVersion::from_parts(1, [7; 16]), [9; 32]);
        let reference = GlobalLeafRunRef::new_base(
            "11aa".to_owned(),
            directory,
            page_count as u64,
            page_count as u64,
            1,
            page_count as u64,
            0,
            encoded_bytes,
            expected_resident_bytes,
            stamp,
            stamp,
        );
        let before = index.storage.request_counts();

        let resident = index
            .read_resident_global_leaf_run_from_backing(&reference, None)
            .unwrap();

        assert_eq!(
            index.storage.request_counts().delta(&before).gets,
            3,
            "preload must authenticate one root plus both directory shards from backing"
        );
        assert_eq!(resident.root().shards().len(), 2);
        assert_eq!(resident.resident_bytes() as u64, expected_resident_bytes);
        assert!(resident.runtime_resident_bytes() as u64 > expected_resident_bytes);
        for ordinal in 0..resident.root().shards().len() {
            assert!(!resident.shard_is_loaded(ordinal).unwrap());
        }
    }

    #[test]
