    #[test]
    fn parallel_live_wal_ranking_matches_exact_distance_and_id_order() {
        let records = (0..4_096)
            .map(|row| {
                VectorRecord::new(
                    format!("tail-{row:04}"),
                    vec![row as f32, (4_095 - row) as f32],
                )
            })
            .collect::<Vec<_>>();
        let options = SearchOptions::exact(7);
        let norms = records
            .iter()
            .map(|record| crate::metric::dot_product(&record.vector, &record.vector).sqrt())
            .collect::<Vec<_>>();

        let ranking = rank_live_wal_exact(
            &VectorMetric::Euclidean,
            &[2_047.5, 2_047.5],
            &options,
            false,
            &records,
            Some(&norms),
        )
        .unwrap();

        assert_eq!(ranking.records_scored, records.len());
        assert_eq!(ranking.rows_evaluated, 0);
        assert_eq!(ranking.rows_passed_filter, 0);
        assert_eq!(
            ranking
                .ranked
                .iter()
                .map(|entry| entry.hit.id.to_string())
                .collect::<Vec<_>>(),
            [
                "tail-2047",
                "tail-2048",
                "tail-2046",
                "tail-2049",
                "tail-2045",
                "tail-2050",
                "tail-2044",
            ]
        );

        let cosine_baseline = rank_live_wal_exact(
            &VectorMetric::Cosine,
            &[2_047.5, 2_047.5],
            &options,
            false,
            &records,
            None,
        )
        .unwrap();
        let cosine_cached = rank_live_wal_exact(
            &VectorMetric::Cosine,
            &[2_047.5, 2_047.5],
            &options,
            false,
            &records,
            Some(&norms),
        )
        .unwrap();
        assert_eq!(
            cosine_cached
                .ranked
                .iter()
                .map(|entry| entry.hit.id.clone())
                .collect::<Vec<_>>(),
            cosine_baseline
                .ranked
                .iter()
                .map(|entry| entry.hit.id.clone())
                .collect::<Vec<_>>()
        );
    }
    #[test]
    fn positioned_flush_locality_orders_records_before_segmenting() {
        let dir = tempfile::tempdir().unwrap();
        let mut index = BorsukIndex::create(IndexConfig {
            uri: dir.path().to_string_lossy().into_owned(),
            metric: VectorMetric::Euclidean,
            dimensions: 2,
            segment_max_vectors: 4,
            ram_budget_bytes: None,
            text: false,
            named_vectors: Default::default(),
        })
        .unwrap();
        let records = (0..8)
            .map(|row| {
                let cluster = if row % 2 == 0 { -10.0 } else { 10.0 };
                VectorRecord::new(
                    format!("row-{row}"),
                    vec![cluster, cluster + row as f32 * 0.01],
                )
            })
            .collect();

        index.add(records).unwrap();
        assert!(index.active_segment_summaries().unwrap().is_empty());
        assert_eq!(index.cell_wal_snapshot.len(), 1);
        assert_eq!(index.get_vector("row-0").unwrap(), Some(vec![-10.0, -10.0]));

        index.flush().unwrap();

        let summaries = index.active_segment_summaries().unwrap();
        assert_eq!(summaries.len(), 2);
        for summary in summaries {
            let (segment, _, _, _) = index.read_segment(&summary).unwrap();
            let negative = segment.records[0].vector[0].is_sign_negative();
            assert!(
                segment
                    .records
                    .iter()
                    .all(|record| record.vector[0].is_sign_negative() == negative)
            );
        }
    }

