        let rows = (0..summary.object_count).collect::<Vec<_>>();
        let first = index
            .segment_vectors_for_rows_ranged(&summary, &rows)
            .unwrap();
        let second = index
            .segment_vectors_for_rows_ranged(&summary, &rows)
            .unwrap();
